@@ -62,7 +62,6 @@ public partial class CreateOrUpdateOrchestrator : TaskOrchestrator<CreateOrUpdat
             internalMetadata.TargetLogAnalyticsWorkspaceId = resource.Properties.TargetLogAnalyticsWorkspaceId;
